import math
def anchor(t, ak):
    name,top,bar,stem,(l,r),o = t
    mid=(l+r)/2
    return {'barmid':(bar,mid),'stem':(stem,mid+stem-mid),'topmid':(top,mid),'botmid':(bar if o=='D' else top,mid),
            'center':((top+bar)/2 if o=='U' else (bar+stem)/2, mid),'stemtip':(top if o=='U' else stem, stem)}[ak]
# fix stem anchor col: stem col
stem_col={'A':3,'B':1,'C':8,'D':6,'E':2,'F':13,'G':7}
def anchor2(t, ak):
    name,top,bar,stem,(l,r),o=t; mid=(l+r)/2
    d={'barmid':(bar,mid),'stemc':(stem,stem_col[name]),'tip':(top if o=='U' else stem, stem_col[name]),
       'cent':((top+bar)/2,mid),'left':(bar,l),'right':(bar,r),'top':(top,mid),'bar':(bar,mid)}
    return d[ak]
target=[[3,0,3,1,0,1],[0]*6,[3,0,0,1,0,1]]
def derived(rs,cs,ak,mode='floor'):
    g=[[0]*6 for _ in range(3)]
    for t in Ts:
        r,c=anchor2(t,ak)
        rr = int(r//rs) if mode=='floor' else int(round(r/rs))
        cc = int(c//cs) if mode=='floor' else int(round(c/cs))
        if 0<=rr<3 and 0<=cc<6:
            g[rr][cc]=3 if t[5]=='U' else 1
    return g
for rs in [2.5,3,4,5,6,7.5]:
    for cs in [2,2.5,3,5]:
        for ak in anchor2 and ['barmid','stemc','tip','cent','left','right','top','bar']:
            for mode in ['floor','round']:
                g=derived(rs,cs,ak,mode)
                if g==target: print("MATCH",rs,cs,ak,mode)
print("done")

